-- Smoke Wagon import (bourbon.smoke_wagon: smokewagon.com — smokewagonwhiskey.com is a parked domain, not the maker), applied 2026-09-24 via the Supabase MCP. No hand steps.
-- Low-yield site: only Small Batch states a proof (100) anywhere in text; Straight Bourbon, Rye and Uncut Unfiltered give mash bill and blending prose with no number ('115-116 plus proof' is a floor, not a statement). Rye has no proof so it is not added. Uncut Unfiltered's row is facts_verified — the mash_style correction the dry run shows is guarded and did not apply.
-- The live Rye page is at /copy-of-smoke-wagon-rye; the plain /rye URL the old sitemap lists is Wix's own retired 'Old first version' of that page (confirmed via its own <title>) and is not crawled.

update cellar.products set image_url = coalesce(image_url, 'https://static.wixstatic.com/media/d5610a_1919d7033abf4e72b2c58f0f8bdd3540~mv2.jpg/v1/fill/w_280,h_180,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/legends_rancho-32.jpg'), producer = coalesce(producer, 'Smoke Wagon'), producer_id = coalesce(producer_id, 'ca9fd6ba-c294-4a22-bca4-3a151559bdac'::uuid), source = 'maker', source_url = 'https://www.smokewagon.com/small-batch', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '7f83e450-4fb3-4596-a202-7001121ffcbe' and facts_verified_at is null;
update cellar.products set image_url = coalesce(image_url, 'https://static.wixstatic.com/media/d5610a_10ba728a18944840bb82528c3adc9f7e~mv2.jpg/v1/crop/x_0,y_125,w_768,h_774/fill/w_264,h_265,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/F6C0E309-8634-4521-ACDA-BB33163A4607_1_1.jpg'), producer = coalesce(producer, 'Smoke Wagon'), producer_id = coalesce(producer_id, 'ca9fd6ba-c294-4a22-bca4-3a151559bdac'::uuid), source_url = 'https://www.smokewagon.com/straight-bourbon', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'b2b55133-ba22-4b32-8ac9-042b5dfa1510' and facts_verified_at is null;
update cellar.products set mash_style = 'high_rye', producer = coalesce(producer, 'Smoke Wagon'), producer_id = coalesce(producer_id, 'ca9fd6ba-c294-4a22-bca4-3a151559bdac'::uuid), source_url = 'https://www.smokewagon.com/uncut-unfiltered', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'a5f995b3-360c-4960-a028-ef4412a4d804' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('7f83e450-4fb3-4596-a202-7001121ffcbe', 'b2b55133-ba22-4b32-8ac9-042b5dfa1510', 'a5f995b3-360c-4960-a028-ef4412a4d804');
insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://static.wixstatic.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);